      "Após a transferência: $\\frac{M-2}{N+2}=\\frac{1}{2} \\Rightarrow 2(M-2)=N+2$.",
      "Substituindo: $2(\\frac{2N}{3}-2)=N+2 \\Rightarrow \\frac{4N}{3}-4=N+2 \\Rightarrow \\frac{N}{3}=6 \\Rightarrow N=18$.",
